(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit62-trap-c3-advanced-1"]={"id":"unit62-trap-c3-advanced-1","unitId":"6-2","chapterIds":["6-2"],"unitType":"advanced","group":"6-2단원 · 선지 변형 유형 · 순서","name":"심화 1","level":"심화","revision":1,"originPage":"unit62","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"순서","parts":[{"name":"U62-P04-02-S1 · 순서","items":[{"paragraphCount":1,"readingLabel":"4문단","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 4문단","passage":"[이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 4문단]\n법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다. 경기도 수원시의 수원 시청 앞 버스 승강장은 조그마한 가꿈을 실천하고 있다. 기존 버스 승강장에 설치된 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지거나 하면 휠체어를 사용하는 장애인은 큰 불편을 겪을 뿐 아니라 눈과 비를 피할 수도 없다. 이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장에 자동 접이식 의자를 설치하였다. 자동 접이식 의자는 사람이 이용하지 않을 때는 자동으로 접혀서 정류장 공간을 확보하고 더 많은 사람이 정류장에서 대기할 수 있게 도와준다. 좁은 인도에 사용하지 않는 의자들이 시민의 통행을 가로막는 경우도 많은데 접이식 의자를 설치하면 이러한 부분도 해결할 수 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["순서"],"why":"기존 버스 승강장의 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지면 휠체어를 사용하는 장애인은 큰 불편을 겪는다.\n근거: “기존 버스 승강장에 설치된 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지거나 하면 휠체어를 사용하는 장애인은 큰 불편을 겪을 뿐 아니라 눈과 비를 피할 수도 없다.”\n4문단에서 확인할 수 있어요.","evidence":{"title":"원래 승강장의 의자는 고정되어 공간을 많이 차지했다.","statement":"기존 버스 승강장의 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지면 휠체어를 사용하는 장애인은 큰 불편을 겪는다.","explanation":"기존 버스 승강장의 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지면 휠체어를 사용하는 장애인은 큰 불편을 겪는다.\n근거: “기존 버스 승강장에 설치된 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지거나 하면 휠체어를 사용하는 장애인은 큰 불편을 겪을 뿐 아니라 눈과 비를 피할 수도 없다.”\n4문단에서 확인할 수 있어요.","valid":["G04:3"],"sources":[{"id":"G04","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"4문단","sentences":[{"id":"G04:1","text":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.","paragraph":0,"memberIds":["G04:1"],"topic":"법과 규칙(법규)에만 맞춰 계획하는 것이 아니라, 쓰는 사람(사용자)을 배려해서 계획하는 것이 가꿈의 시작이다."},{"id":"G04:2","text":"경기도 수원시의 수원 시청 앞 버스 승강장은 조그마한 가꿈을 실천하고 있다.","paragraph":0,"memberIds":["G04:2"],"topic":"경기도 수원시의 수원 시청 앞 버스 정류장(승강장)은 작은 가꿈을 실제로 하고(실천하고) 있다."},{"id":"G04:3","text":"기존 버스 승강장에 설치된 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지거나 하면 휠체어를 사용하는 장애인은 큰 불편을 겪을 뿐 아니라 눈과 비를 피할 수도 없다.","paragraph":0,"memberIds":["G04:3"],"topic":"원래 정류장의 의자들은 한자리에 붙어 있어서(고정되어 있어서) 자리를 많이 차지했다. 그래서 사람이 많아지면 휠체어를 타는 장애인은 몹시 불편하고, 눈과 비를 피할 수도 없었다."},{"id":"G04:4","text":"이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장에 자동 접이식 의자를 설치하였다.","paragraph":0,"memberIds":["G04:4"],"topic":"이런 불편을 없애고 모두를 배려하려고 정류장에 저절로 접히는 의자(자동 접이식 의자)를 놓았다."},{"id":"G04:5","text":"자동 접이식 의자는 사람이 이용하지 않을 때는 자동으로 접혀서 정류장 공간을 확보하고 더 많은 사람이 정류장에서 대기할 수 있게 도와준다.","paragraph":0,"memberIds":["G04:5"],"topic":"자동 접이식 의자는 아무도 앉지 않을 때 저절로 접혀서 정류장 공간을 넓혀 주고, 더 많은 사람이 정류장에서 기다릴 수 있게 해 준다."},{"id":"G04:6","text":"좁은 인도에 사용하지 않는 의자들이 시민의 통행을 가로막는 경우도 많은데 접이식 의자를 설치하면 이러한 부분도 해결할 수 있다.","paragraph":0,"memberIds":["G04:6"],"topic":"좁은 인도에서는 아무도 안 쓰는 의자가 사람들이 지나가는 길을 막는 일도 많은데, 접이식 의자를 놓으면 이 문제도 풀 수 있다."}]}]},"id":"U62-P04-02-S1","type":"mc","sent":"4문단의 내용과 맞는 설명은?","options":["기존 버스 승강장의 의자들은 자동으로 접혀 많은 공간을 차지하고, 사람들이 많아지면 휠체어를 사용하는 장애인은 큰 불편을 겪는다.","사용자를 배려하여 계획하는 것이 아닌, 법규에만 맞춰 계획하는 것이 가꿈의 시작이다.","기존 버스 승강장의 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지면 휠체어를 사용하는 장애인은 큰 불편을 겪는다.","이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장의 의자를 모두 없앴다.","자동 접이식 의자는 사람이 이용할 때 자동으로 접혀서 정류장 공간을 확보한다."],"answer":"기존 버스 승강장의 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지면 휠체어를 사용하는 장애인은 큰 불편을 겪는다.","choiceReviews":{"기존 버스 승강장의 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지면 휠체어를 사용하는 장애인은 큰 불편을 겪는다.":{"reason":"기존 버스 승강장의 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지면 휠체어를 사용하는 장애인은 큰 불편을 겪는다.\n근거: “기존 버스 승강장에 설치된 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지거나 하면 휠체어를 사용하는 장애인은 큰 불편을 겪을 뿐 아니라 눈과 비를 피할 수도 없다.”\n4문단에서 확인할 수 있어요.","edits":[]},"기존 버스 승강장의 의자들은 자동으로 접혀 많은 공간을 차지하고, 사람들이 많아지면 휠체어를 사용하는 장애인은 큰 불편을 겪는다.":{"reason":"바르게 고치면: 기존 버스 승강장의 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지면 휠체어를 사용하는 장애인은 큰 불편을 겪는다.\n기존 버스 승강장의 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지면 휠체어를 사용하는 장애인은 큰 불편을 겪는다.\n근거: “기존 버스 승강장에 설치된 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지거나 하면 휠체어를 사용하는 장애인은 큰 불편을 겪을 뿐 아니라 눈과 비를 피할 수도 없다.”\n4문단에서 확인할 수 있어요.","edits":[{"start":16,"end":24,"before":"자동으로 접혀 ","after":"고정되어 있어 "}]},"사용자를 배려하여 계획하는 것이 아닌, 법규에만 맞춰 계획하는 것이 가꿈의 시작이다.":{"reason":"바르게 고치면: 법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.\n법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.\n근거: “법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.”\n4문단에서 확인할 수 있어요.","edits":[{"start":0,"end":5,"before":"사용자를 ","after":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 "},{"start":18,"end":38,"before":"아닌, 법규에만 맞춰 계획하는 것이 ","after":""}]},"이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장의 의자를 모두 없앴다.":{"reason":"바르게 고치면: 이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장에 자동 접이식 의자를 설치하였다.\n이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장에 자동 접이식 의자를 설치하였다.\n근거: “이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장에 자동 접이식 의자를 설치하였다.”\n4문단에서 확인할 수 있어요.","edits":[{"start":27,"end":32,"before":"승강장의 ","after":"승강장에 자동 접이식 "},{"start":36,"end":43,"before":"모두 없앴다.","after":"설치하였다."}]},"자동 접이식 의자는 사람이 이용할 때 자동으로 접혀서 정류장 공간을 확보한다.":{"reason":"바르게 고치면: 자동 접이식 의자는 사람이 이용하지 않을 때는 자동으로 접혀서 정류장 공간을 확보한다.\n자동 접이식 의자는 사람이 이용하지 않을 때는 자동으로 접혀서 정류장 공간을 확보한다.\n근거: “자동 접이식 의자는 사람이 이용하지 않을 때는 자동으로 접혀서 정류장 공간을 확보하고 더 많은 사람이 정류장에서 대기할 수 있게 도와준다.”\n4문단에서 확인할 수 있어요.","edits":[{"start":15,"end":21,"before":"이용할 때 ","after":"이용하지 않을 때는 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"2c3eeb87b89996e49f6f2cfe5f488062d2692f6a3d2d8326d6c9fd08807c6338"}]},{"name":"U62-P06-01-S1 · 순서","items":[{"paragraphCount":1,"readingLabel":"6문단","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 6문단","passage":"[이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 6문단]\n자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다. 그동안 관심을 두지 않고 지나치던 공간에서 새로운 사람들을 만나고 소통하는 과정을 통해 자신이 살아가는 지역을 다시 발견하고 인식하게 된다. 이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["순서"],"why":"자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 된다.\n근거: “자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다.”\n6문단에서 확인할 수 있어요.","evidence":{"title":"주변 공간을 보살피면 지역 살림에 관심을 둔다.","statement":"자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 된다.","explanation":"자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 된다.\n근거: “자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다.”\n6문단에서 확인할 수 있어요.","valid":["G06:1"],"sources":[{"id":"G06","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"6문단","sentences":[{"id":"G06:1","text":"자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다.","paragraph":0,"memberIds":["G06:1"],"topic":"내 주변 공간을 보살피다 보면 동네 살림(지역 살림)에 관심이 생기고, 서로 이야기를 나눌 수 있는 곳(소통할 수 있는 지점)을 찾게 된다."},{"id":"G06:2","text":"그동안 관심을 두지 않고 지나치던 공간에서 새로운 사람들을 만나고 소통하는 과정을 통해 자신이 살아가는 지역을 다시 발견하고 인식하게 된다.","paragraph":0,"memberIds":["G06:2"],"topic":"그동안 관심 없이 지나치던 곳에서 새로운 사람들을 만나 이야기를 나누다 보면, 내가 사는 동네를 새로 보고 분명히 알게(인식하게) 된다."},{"id":"G06:3","text":"이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.","paragraph":0,"memberIds":["G06:3"],"topic":"이런 과정을 거치며 함께 살아가는 공동체가 얼마나 중요한지도 깨닫게 될 것이다."}]}]},"id":"U62-P06-01-S1","type":"mc","sent":"6문단의 내용과 맞는 설명은?","options":["지역 살림에 관심을 두다 보면 자신의 주변 공간을 보살피게 된다.","자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 된다.","자신의 주변 공간을 보살피다 보면 서로 소통할 수 있는 지점이 사라지게 된다.","그동안 관심을 두지 않고 지나치던 공간에서 새로운 사람들을 만나고 소통하는 과정을 통해 자신이 살지 않는 새로운 지역을 발견하게 된다.","이런 과정을 통해 혼자 살아가는 생활의 편리함을 깨닫게 될 것이다."],"answer":"자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 된다.","choiceReviews":{"자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 된다.":{"reason":"자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 된다.\n근거: “자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다.”\n6문단에서 확인할 수 있어요.","edits":[]},"지역 살림에 관심을 두다 보면 자신의 주변 공간을 보살피게 된다.":{"reason":"바르게 고치면: 자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 된다.\n자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 된다.\n근거: “자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다.”\n6문단에서 확인할 수 있어요.","edits":[{"start":0,"end":3,"before":"지역 ","after":"자신의 주변 공간을 보살피다 보면 지역 "},{"start":11,"end":33,"before":"두다 보면 자신의 주변 공간을 보살피게 ","after":"두게 "}]},"자신의 주변 공간을 보살피다 보면 서로 소통할 수 있는 지점이 사라지게 된다.":{"reason":"바르게 고치면: 자신의 주변 공간을 보살피다 보면 서로 소통할 수 있는 지점을 발견하게 된다.\n자신의 주변 공간을 보살피다 보면 서로 소통할 수 있는 지점을 발견하게 된다.\n근거: “자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다.”\n6문단에서 확인할 수 있어요.","edits":[{"start":31,"end":40,"before":"지점이 사라지게 ","after":"지점을 발견하게 "}]},"그동안 관심을 두지 않고 지나치던 공간에서 새로운 사람들을 만나고 소통하는 과정을 통해 자신이 살지 않는 새로운 지역을 발견하게 된다.":{"reason":"바르게 고치면: 그동안 관심을 두지 않고 지나치던 공간에서 새로운 사람들을 만나고 소통하는 과정을 통해 자신이 살아가는 지역을 다시 발견하고 인식하게 된다.\n그동안 관심을 두지 않고 지나치던 공간에서 새로운 사람들을 만나고 소통하는 과정을 통해 자신이 살아가는 지역을 다시 발견하고 인식하게 된다.\n근거: “그동안 관심을 두지 않고 지나치던 공간에서 새로운 사람들을 만나고 소통하는 과정을 통해 자신이 살아가는 지역을 다시 발견하고 인식하게 된다.”\n6문단에서 확인할 수 있어요.","edits":[{"start":53,"end":63,"before":"살지 않는 새로운 ","after":"살아가는 "},{"start":67,"end":72,"before":"발견하게 ","after":"다시 발견하고 인식하게 "}]},"이런 과정을 통해 혼자 살아가는 생활의 편리함을 깨닫게 될 것이다.":{"reason":"바르게 고치면: 이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.\n이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.\n근거: “이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.”\n6문단에서 확인할 수 있어요.","edits":[{"start":10,"end":13,"before":"혼자 ","after":"함께 "},{"start":18,"end":27,"before":"생활의 편리함을 ","after":"공동체의 중요성 또한 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"41894660deb8a5ef518ad8ecd60ba0f371f6dfa69fba555bc56adf6a00f6c27f"}]}]};})(window);
